// CO section boundaries based on question types
function getCoSections(data) {
  // Determine image questions, audio-only, text-answers ranges
  let lastImage = 0, firstText = 39;
  data.forEach(q => { if (q.image) lastImage = q.id; });
  data.forEach(q => { if (q.opts && q.opts.length > 0 && !firstText) firstText = q.id; });
  // Find first question with text options
  for (let i = 0; i < data.length; i++) { if (data[i].opts && data[i].opts.length > 0) { firstText = data[i].id; break; } }
  // Find last audio-only (no image, no opts) before text starts
  let lastAudioOnly = lastImage;
  for (let i = lastImage; i < data.length; i++) { if (!data[i].opts || data[i].opts.length === 0) lastAudioOnly = data[i].id; else break; }
  return [
    { range: [1, lastImage], section: 1, sectionTitle: "Comprendre un message court", level: "A1/A2" },
    { range: [lastImage+1, lastAudioOnly], section: 2, sectionTitle: "Comprendre une interaction", level: "A2/B1" },
    { range: [lastAudioOnly+1, Math.min(lastAudioOnly+10, 20)], section: 3, sectionTitle: "Comprendre un message long", level: "B1/B2" },
    { range: [Math.min(lastAudioOnly+11, 21), 30], section: 4, sectionTitle: "Comprendre en tant qu'auditeur", level: "B2/C1" },
    { range: [31, 39], section: 5, sectionTitle: "Comprendre un exposé", level: "C1/C2" },
  ];
}

function generateCoFile(key, num, data) {
  const varName = `questionsTest${num}`;
  const secName = `sectionsTest${num}`;
  const questions = data.map(q => {
    const type = q.image ? 'image' : (q.opts && q.opts.length > 0 ? 'text-answers' : 'audio-only');
    const instr = type === 'image' ? "Écoutez les 4 propositions. Choisissez celle qui correspond à l'image." :
                  type === 'audio-only' ? "Écoutez l'extrait sonore et les 4 propositions. Choisissez la bonne réponse." :
                  "Écoutez le document sonore et la question. Choisissez la bonne réponse.";
    let obj = `  { id: ${q.id}, type: '${type}', instruction: "${instr}"`;
    if (q.image) obj += `, image: '${q.image}'`;
    obj += `, audio: '${q.audio}', correctAnswer: ${q.ca}`;
    if (q.opts) obj += `, options: ${JSON.stringify(q.opts)}`;
    else obj += `, options: null`;
    obj += ` }`;
    return obj;
  });

  const sections = getCoSections(data);
  const sectionLines = sections.map(s => `  { range: [${s.range[0]}, ${s.range[1]}], section: ${s.section}, sectionTitle: "${s.sectionTitle}", level: "${s.level}" }`);

  return `export const ${varName} = [\n${questions.join(',\n')}\n];\n\nconst sectionMeta = [\n${sectionLines.join(',\n')}\n];\nsectionMeta.forEach(({ range, section, sectionTitle, level }) => {\n  ${varName}.forEach(q => { if (q.id >= range[0] && q.id <= range[1]) { q.section = section; q.sectionTitle = sectionTitle; q.level = level; } });\n});\n\nexport const ${secName} = sectionMeta.map(s => ({ section: s.section, title: s.sectionTitle, level: s.level, range: s.range }));\n`;
}

function generateCeFile(key, num, data) {
  const varName = `questionsCeTest${num}`;
  const secName = `sectionsCeTest${num}`;
  const questions = data.map(q => {
    let obj = `  { id: ${q.id}, type: 'reading', image: '${q.image}', options: ${JSON.stringify(q.opts)}, correctAnswer: ${q.ca} }`;
    return obj;
  });

  return `export const ${varName} = [\n${questions.join(',\n')}\n];\n\nconst sectionMeta = [\n  { range: [1, 10], section: 1, sectionTitle: "Comprendre un document court", level: "A1/A2" },\n  { range: [11, 20], section: 2, sectionTitle: "Comprendre un document informatif", level: "B1/B2" },\n  { range: [21, 30], section: 3, sectionTitle: "Comprendre un texte argumentatif", level: "B2/C1" },\n  { range: [31, 39], section: 4, sectionTitle: "Comprendre un texte complexe", level: "C1/C2" },\n];\nsectionMeta.forEach(({ range, section, sectionTitle, level }) => {\n  ${varName}.forEach(q => { if (q.id >= range[0] && q.id <= range[1]) { q.section = section; q.sectionTitle = sectionTitle; q.level = level; } });\n});\n\nexport const ${secName} = sectionMeta.map(s => ({ section: s.section, title: s.sectionTitle, level: s.level, range: s.range }));\n`;
}

// Generate CO files
for (let n = 36; n <= 40; n++) {
  const key = `co${n}`;
  const content = generateCoFile(key, n, rawData[key]);
  writeFileSync(`src/data/questions-test${n}.js`, content, 'utf8');
  console.log(`Generated questions-test${n}.js (${rawData[key].length} questions)`);
}

// Generate CE files
for (let n = 31; n <= 35; n++) {
  const key = `ce${n}`;
  const content = generateCeFile(key, n, rawData[key]);
  writeFileSync(`src/data/questions-ce-test${n}.js`, content, 'utf8');
  console.log(`Generated questions-ce-test${n}.js (${rawData[key].length} questions)`);
}

console.log('\nAll 10 data files generated successfully!');
